<?php
namespace App\Controllers;
use App\Core\{Controller,Database,Flash};
class AdminController extends Controller {
 private function audit(string $action,string $type,mixed $id=null):void{Database::connection()->prepare('INSERT INTO audit_logs(actor_user_id,action,entity_type,entity_id,ip_address) VALUES(?,?,?,?,?)')->execute([$_SESSION['user_id'],$action,$type,$id?:null,$_SERVER['REMOTE_ADDR']??null]);}
 public function index():void{$this->requireAuth(['ADMIN']);$d=Database::connection();$stats=$d->query("SELECT (SELECT COUNT(*) FROM rental_orders WHERE order_status NOT IN('COMPLETED','CANCELLED')) open_orders,(SELECT COUNT(*) FROM rental_orders WHERE due_at<NOW() AND order_status IN('RENTED','PARTIALLY_RETURNED')) overdue,(SELECT COUNT(*) FROM containers WHERE lifecycle_status='AVAILABLE') available,(SELECT COUNT(*) FROM containers WHERE lifecycle_status IN('CLEANING','RETURNED_DIRTY')) cleaning,(SELECT COALESCE(SUM(amount),0) FROM payments WHERE status='PAID') revenue,(SELECT COALESCE(SUM(amount),0) FROM deposit_transactions WHERE transaction_type='HOLD' AND status='COMPLETED') deposits")->fetch();$recent=$d->query('SELECT o.*,u.name customer FROM rental_orders o JOIN users u ON u.id=o.user_id ORDER BY o.created_at DESC LIMIT 8')->fetchAll();$this->view('admin/dashboard',['title'=>'Trung tâm vận hành','stats'=>$stats,'recent'=>$recent]);}
 public function products():void{$this->requireAuth(['ADMIN']);$d=Database::connection();$this->view('admin/products',['title'=>'Quản là hộp','products'=>$d->query('SELECT p.*,c.name category,(SELECT COUNT(*) FROM containers WHERE product_id=p.id) total,(SELECT COUNT(*) FROM containers WHERE product_id=p.id AND lifecycle_status="AVAILABLE") available FROM products p JOIN categories c ON c.id=p.category_id ORDER BY p.id DESC')->fetchAll(),'categories'=>$d->query('SELECT * FROM categories')->fetchAll()]);}
 public function saveProduct():void{$this->requireAuth(['ADMIN']);verify_csrf();$name=trim($_POST['name']??'');$sku=strtoupper(trim($_POST['sku']??''));$category=(int)($_POST['category_id']??0);$capacity=(int)($_POST['capacity_ml']??0);$price=(float)($_POST['rental_price']??0);$deposit=(float)($_POST['deposit_amount']??0);$image=trim($_POST['image_url']??'');if(!$name||!preg_match('/^[A-Z0-9-]{3,40}$/',$sku)||$category<1||$capacity<1||$price<0||$deposit<0||($image!==''&&!filter_var($image,FILTER_VALIDATE_URL))){Flash::set('error','Vui lòng kiểm tra thông tin sản phẩm.');$this->redirect('/admin/products');}$slug=trim(preg_replace('/[^a-z0-9]+/','-',strtolower(iconv('UTF-8','ASCII//TRANSLIT',$name))),'-').'-'.strtolower($sku);$d=Database::connection();$q=$d->prepare('INSERT INTO products(category_id,sku,name,slug,description,material,capacity_ml,dimensions,weight_g,food_types,image_url,rental_price,deposit_amount,late_fee_per_day,max_rental_days) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)');$q->execute([$category,$sku,$name,$slug,trim($_POST['description']??''),trim($_POST['material']??''),$capacity,trim($_POST['dimensions']??''),(int)($_POST['weight_g']??0),trim($_POST['food_types']??''),$image,$price,$deposit,max(0,(float)($_POST['late_fee_per_day']??0)),max(1,(int)($_POST['max_rental_days']??7))]);$id=$d->lastInsertId();$this->audit('CREATE_PRODUCT','products',$id);Flash::set('success','Đã thêm sản phẩm.');$this->redirect('/admin/products');}
 public function updateProduct():void{$this->requireAuth(['ADMIN']);verify_csrf();$id=(int)($_POST['id']??0);$name=trim($_POST['name']??'');$sku=strtoupper(trim($_POST['sku']??''));$category=(int)($_POST['category_id']??0);$capacity=(int)($_POST['capacity_ml']??0);$price=(float)($_POST['rental_price']??0);$deposit=(float)($_POST['deposit_amount']??0);$image=trim($_POST['image_url']??'');$status=($_POST['status']??'ACTIVE')==='INACTIVE'?'INACTIVE':'ACTIVE';if($id<1||$name===''||!preg_match('/^[A-Z0-9-]{3,40}$/',$sku)||$category<1||$capacity<1||$price<0||$deposit<0||($image!==''&&!filter_var($image,FILTER_VALIDATE_URL))){Flash::set('error','Vui lòng kiểm tra lại thông tin sản phẩm.');$this->redirect('/admin/products');}$d=Database::connection();if($status==='INACTIVE'){$check=$d->prepare("SELECT COUNT(*) FROM containers WHERE product_id=? AND lifecycle_status IN ('RESERVED','RENTED')");$check->execute([$id]);if((int)$check->fetchColumn()>0){Flash::set('error','Sản phẩm đang có hộp được giữ hoặc cho thuê.');$this->redirect('/admin/products');}}$slug=trim(preg_replace('/[^a-z0-9]+/','-',strtolower(iconv('UTF-8','ASCII//TRANSLIT',$name))),'-').'-'.strtolower($sku);try{$q=$d->prepare('UPDATE products SET category_id=?,sku=?,name=?,slug=?,description=?,material=?,capacity_ml=?,dimensions=?,weight_g=?,food_types=?,image_url=?,rental_price=?,deposit_amount=?,late_fee_per_day=?,max_rental_days=?,status=? WHERE id=?');$q->execute([$category,$sku,$name,$slug,trim($_POST['description']??''),trim($_POST['material']??''),$capacity,trim($_POST['dimensions']??''),(int)($_POST['weight_g']??0),trim($_POST['food_types']??''),$image,$price,$deposit,max(0,(float)($_POST['late_fee_per_day']??0)),max(1,(int)($_POST['max_rental_days']??7)),$status,$id]);$this->audit('UPDATE_PRODUCT','products',$id);Flash::set('success','Đã cập nhật sản phẩm.');}catch(\Throwable $e){Flash::set('error','Không thể cập nhật. SKU hoặc đường dẫn có thể đã được dùng.');}$this->redirect('/admin/products');}
 public function deleteProduct():void{$this->requireAuth(['ADMIN']);verify_csrf();$id=(int)($_POST['id']??0);$d=Database::connection();$q=$d->prepare("SELECT COUNT(*) FROM containers WHERE product_id=? AND lifecycle_status IN ('RESERVED','RENTED')");$q->execute([$id]);if((int)$q->fetchColumn()>0){Flash::set('error','Không thể ngừng sản phẩm đang có hộp được giữ hoặc đang cho thuê.');$this->redirect('/admin/products');}$d->prepare("UPDATE products SET status='INACTIVE' WHERE id=?")->execute([$id]);$this->audit('DEACTIVATE_PRODUCT','products',$id);Flash::set('success','Đã ngừng kinh doanh sản phẩm; lịch sử thuê được giữ nguyên.');$this->redirect('/admin/products');}
 public function containers():void{$this->requireAuth(['ADMIN']);$d=Database::connection();$this->view('admin/containers',['title'=>'Vòng đời hộp','containers'=>$d->query('SELECT c.*,p.name product,l.name location FROM containers c JOIN products p ON p.id=c.product_id LEFT JOIN locations l ON l.id=c.location_id ORDER BY c.id DESC LIMIT 150')->fetchAll(),'products'=>$d->query('SELECT id,name FROM products')->fetchAll(),'locations'=>$d->query('SELECT id,name FROM locations')->fetchAll()]);}
 public function saveContainer():void{$this->requireAuth(['ADMIN']);verify_csrf();$d=Database::connection();$quantity=max(1,min(100,(int)($_POST['quantity']??1)));try{$d->beginTransaction();for($i=0;$i<$quantity;$i++){$serial=trim($_POST['serial_code']??'');if(!$serial)$serial='RB-'.date('ymd').'-'.strtoupper(bin2hex(random_bytes(3)));if($quantity>1)$serial.='-'.str_pad((string)($i+1),3,'0',STR_PAD_LEFT);$q=$d->prepare('INSERT INTO containers(product_id,location_id,serial_code,qr_token,lifecycle_status) VALUES(?,?,?,?,?)');$q->execute([(int)$_POST['product_id'],(int)$_POST['location_id'],$serial,bin2hex(random_bytes(32)),'AVAILABLE']);}$this->audit('CREATE_CONTAINERS','containers');$d->commit();Flash::set('success',"Đã thêm $quantity hộp và cấp token QR.");}catch(\Throwable $e){if($d->inTransaction())$d->rollBack();Flash::set('error','Không thể thêm hộp. Hãy kiểm tra mã serial và dữ liệu.');}$this->redirect('/admin/containers');}
 public function locations():void{$this->requireAuth(['ADMIN']);$this->view('admin/locations',['title'=>'Điểm nhận và trả','locations'=>Database::connection()->query('SELECT l.*,COUNT(c.id) container_count FROM locations l LEFT JOIN containers c ON c.location_id=l.id GROUP BY l.id')->fetchAll()]);}
 public function saveLocation():void{$this->requireAuth(['ADMIN']);verify_csrf();$d=Database::connection();$values=[trim($_POST['name']??''),trim($_POST['address']??''),trim($_POST['phone']??''),trim($_POST['opening_hours']??''),(int)($_POST['capacity']??0)];if($values[0]===''||$values[1]===''){Flash::set('error','Tên điểm và địa chỉ là bắt buộc.');$this->redirect('/admin/locations');}$q=$d->prepare('INSERT INTO locations(name,address,phone,opening_hours,capacity) VALUES(?,?,?,?,?)');$q->execute($values);$id=$d->lastInsertId();$this->audit('CREATE_LOCATION','locations',$id);Flash::set('success','Đã thêm điểm nhận/trả.');$this->redirect('/admin/locations');}
 public function updateLocation():void{$this->requireAuth(['ADMIN']);verify_csrf();$id=(int)($_POST['id']??0);$name=trim($_POST['name']??'');$address=trim($_POST['address']??'');if($id<1||$name===''||$address===''){Flash::set('error','Tên điểm và địa chỉ là bắt buộc.');$this->redirect('/admin/locations');}$status=($_POST['status']??'ACTIVE')==='INACTIVE'?'INACTIVE':'ACTIVE';$d=Database::connection();if($status==='INACTIVE'){$q=$d->prepare("SELECT (SELECT COUNT(*) FROM containers WHERE location_id=? AND lifecycle_status NOT IN ('RETIRED','LOST'))+(SELECT COUNT(*) FROM rental_orders WHERE (pickup_location_id=? OR planned_return_location_id=?) AND order_status IN ('PENDING_PAYMENT','CONFIRMED','READY_FOR_PICKUP','RENTED','PARTIALLY_RETURNED'))");$q->execute([$id,$id,$id]);if((int)$q->fetchColumn()>0){Flash::set('error','Điểm này còn hộp hoặc đơn đang hoạt động nên chưa thể ngừng.');$this->redirect('/admin/locations');}}$d->prepare('UPDATE locations SET name=?,address=?,phone=?,opening_hours=?,capacity=?,status=? WHERE id=?')->execute([$name,$address,trim($_POST['phone']??''),trim($_POST['opening_hours']??''),max(0,(int)($_POST['capacity']??0)),$status,$id]);$this->audit('UPDATE_LOCATION','locations',$id);Flash::set('success','Đã cập nhật điểm nhận/trả.');$this->redirect('/admin/locations');}
 public function deleteLocation():void{$this->requireAuth(['ADMIN']);verify_csrf();$id=(int)($_POST['id']??0);$d=Database::connection();$q=$d->prepare("SELECT (SELECT COUNT(*) FROM containers WHERE location_id=? AND lifecycle_status NOT IN ('RETIRED','LOST'))+(SELECT COUNT(*) FROM rental_orders WHERE (pickup_location_id=? OR planned_return_location_id=?) AND order_status IN ('PENDING_PAYMENT','CONFIRMED','READY_FOR_PICKUP','RENTED','PARTIALLY_RETURNED'))");$q->execute([$id,$id,$id]);if((int)$q->fetchColumn()>0){Flash::set('error','Điểm này còn hộp hoặc đơn đang hoạt động nên chưa thể ngừng.');$this->redirect('/admin/locations');}$d->prepare("UPDATE locations SET status='INACTIVE' WHERE id=?")->execute([$id]);$this->audit('DEACTIVATE_LOCATION','locations',$id);Flash::set('success','Đã ngừng điểm nhận/trả; dữ liệu lịch sử được giữ lại.');$this->redirect('/admin/locations');}
 public function users():void{$this->requireAuth(['ADMIN']);$this->view('admin/users',['title'=>'Tài khoản','users'=>Database::connection()->query('SELECT u.id,u.name,u.email,u.phone,u.status,u.created_at,r.name role_name,r.code role_code FROM users u JOIN roles r ON r.id=u.role_id ORDER BY u.id DESC')->fetchAll()]);}
 public function userStatus():void{$this->requireAuth(['ADMIN']);verify_csrf();$id=(int)($_POST['id']??0);$status=($_POST['status']??'')==='LOCKED'?'LOCKED':'ACTIVE';if($id!==(int)$_SESSION['user_id']){$d=Database::connection();$d->prepare('UPDATE users SET status=? WHERE id=?')->execute([$status,$id]);$this->audit('CHANGE_USER_STATUS','users',$id);Flash::set('success','Đã cập nhật trạng thói Tài khoản.');}$this->redirect('/admin/users');}
 public function userRole():void{$this->requireAuth(['ADMIN']);verify_csrf();$id=(int)($_POST['id']??0);$role=$_POST['role_code']??'';if($id===(int)$_SESSION['user_id']){Flash::set('error','Không thể thay đổi vai trả đang đăng nhập.');$this->redirect('/admin/users');}if(!in_array($role,['ADMIN','STAFF','CUSTOMER','PARTNER'],true)){Flash::set('error','Vai trả Không hợp lệ.');$this->redirect('/admin/users');}$d=Database::connection();$q=$d->prepare('UPDATE users SET role_id=(SELECT id FROM roles WHERE code=?) WHERE id=?');$q->execute([$role,$id]);$this->audit('CHANGE_USER_ROLE','users',$id);Flash::set('success','Đã cập nhật vai trả.');$this->redirect('/admin/users');}
 public function saveCategory():void{$this->requireAuth(['ADMIN']);verify_csrf();$name=trim($_POST['name']??'');$description=trim($_POST['description']??'');if($name===''){Flash::set('error','Tên danh mục là bắt buộc.');$this->redirect('/admin/products');}$slug=trim(preg_replace('/[^a-z0-9]+/','-',strtolower(iconv('UTF-8','ASCII//TRANSLIT',$name))),'-');$d=Database::connection();try{$q=$d->prepare('INSERT INTO categories(name,slug,description) VALUES(?,?,?)');$q->execute([$name,$slug,$description]);$this->audit('CREATE_CATEGORY','categories',$d->lastInsertId());Flash::set('success','Đã thêm danh mục.');}catch(\Throwable $e){Flash::set('error','Tên hoặc đường dẫn danh mục đã tồn tại.');}$this->redirect('/admin/products');}
 public function updateCategory():void{$this->requireAuth(['ADMIN']);verify_csrf();$id=(int)($_POST['id']??0);$name=trim($_POST['name']??'');if($id<1||$name===''){Flash::set('error','Tên danh mục là bắt buộc.');$this->redirect('/admin/products');}$slug=trim(preg_replace('/[^a-z0-9]+/','-',strtolower(iconv('UTF-8','ASCII//TRANSLIT',$name))),'-');try{$d=Database::connection();$d->prepare('UPDATE categories SET name=?,slug=?,description=?,status=? WHERE id=?')->execute([$name,$slug,trim($_POST['description']??''),(int)($_POST['status']??1)?1:0,$id]);$this->audit('UPDATE_CATEGORY','categories',$id);Flash::set('success','Đã cập nhật danh mục.');}catch(\Throwable $e){Flash::set('error','Không thể cập nhật danh mục. Tên có thể đã được dùng.');}$this->redirect('/admin/products');}
 public function deleteCategory():void{$this->requireAuth(['ADMIN']);verify_csrf();$id=(int)($_POST['id']??0);$d=Database::connection();$q=$d->prepare('SELECT COUNT(*) FROM products WHERE category_id=?');$q->execute([$id]);if((int)$q->fetchColumn()>0){Flash::set('error','Hãy chuyển sản phẩm sang danh mục khác trước khi xóa danh mục này.');$this->redirect('/admin/products');}$d->prepare('DELETE FROM categories WHERE id=?')->execute([$id]);$this->audit('DELETE_CATEGORY','categories',$id);Flash::set('success','Đã xóa danh mục.');$this->redirect('/admin/products');}
 public function reports():void{$this->requireAuth(['ADMIN']);$d=Database::connection();$rows=$d->query('SELECT DATE(created_at) day,COUNT(*) orders_total,SUM(rental_subtotal) rental_revenue,SUM(deposit_total) deposits FROM rental_orders GROUP BY DATE(created_at) ORDER BY day DESC LIMIT 30')->fetchAll();$inventory=$d->query('SELECT p.name,COUNT(c.id) total,SUM(c.lifecycle_status="AVAILABLE") available,SUM(c.lifecycle_status="RENTED") rented,SUM(c.lifecycle_status IN("CLEANING","RETURNED_DIRTY")) cleaning,SUM(c.lifecycle_status="MAINTENANCE") maintenance FROM products p LEFT JOIN containers c ON c.product_id=p.id GROUP BY p.id')->fetchAll();$this->view('admin/reports',['title'=>'Báo cáo vận hành','rows'=>$rows,'inventory'=>$inventory]);}
}
